import json
task=json.load(open('task.json'))
sizes={p['index']:p['size_m'] for p in task['parts']}
# (x,y) from top view for each part
XY={
0:(0.415,0.0),
1:(0.33,-0.07),2:(0.49,-0.07),3:(0.33,0.07),4:(0.49,0.07),
7:(0.33,0.0),8:(0.49,0.0),
5:(0.415,0.085),12:(0.415,0.07),6:(0.415,0.075),
10:(0.485,-0.07),11:(0.485,0.07),16:(0.47,0.07),17:(0.485,0.07),
13:(0.33,-0.07),14:(0.49,-0.07),15:(0.415,-0.07),
18:(0.49,0.03),
9:(0.31,0.0),
}
def footprint(i):
    x,y=XY[i];s=sizes[i]
    return (x-s[0]/2,x+s[0]/2,y-s[1]/2,y+s[1]/2)
def xy_overlap(a,b,eps=1e-4):
    A=footprint(a);B=footprint(b)
    ox=min(A[1],B[1])-max(A[0],B[0])
    oy=min(A[3],B[3])-max(A[2],B[2])
    return ox>eps and oy>eps
# assign z by stacking: place in order of increasing assigned z; for a part, support_top =
# max over already-assigned parts j with xy_overlap of (top_j); if none -> 0 (table)
order=list(XY)
top={}
z={}
# iterate to fixpoint (topological): repeatedly assign
import sys
unassigned=set(order)
for it in range(100):
    for i in list(unassigned):
        s=sizes[i]
        sup=0.0
        for j in top:
            if xy_overlap(i,j):
                sup=max(sup,top[j])
        z[i]=sup+s[2]/2
        top[i]=sup+s[2]
        unassigned.remove(i)
    if not unassigned:break
for i in sorted(XY):
    print(i, XY[i], "z=%.4f"%z[i], "top=%.4f"%top[i])

